import { attachControl } from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

// Drags turn the camera this many times as far as the library default.
const DRAG_TURN_FACTOR = 2;

export function attachFastOrbit(
    camera: ArcRotateCamera,
    canvas: HTMLCanvasElement,
    scene: SceneContext,
): () => void {
    // Assumes angularSensibility is a divisor (higher = slower turning), as in
    // Babylon.js. Halving it doubles the turn per pixel of mouse or touch movement.
    const originalSensibility = camera.angularSensibility;
    camera.angularSensibility = originalSensibility / DRAG_TURN_FACTOR;

    const detachControls = attachControl(camera, canvas, scene);

    let disposed = false;
    return () => {
        if (disposed) return;
        disposed = true;
        detachControls();
        camera.angularSensibility = originalSensibility;
    };
}
```

I could not write this to disk, so please save the block above as `/home/dev/a91b90/app/src/fast-orbit.ts`. I also did not look anything up in the library itself, since it isn't on this machine.

I'm not sure of several things:
- **Sensitivity semantics:** I assumed `angularSensibility` is a divisor, which the declarations don't say. If it is a multiplier in Lite, the factor should be applied as a multiplication instead.
- **Glide:** I assumed the inertial glide is derived from the same sensitivity, so halving it also doubles the glide. If the glide is computed separately, it will still need its own change.
- **Imports:** I assumed `attachControl` and the types are exported from the package root `@babylonjs/lite`. The declarations only show internal paths.
- **Restore on dispose:** the cleanup restores the sensitivity value captured at attach time, so any change the app makes to it during the session will be overwritten.
